- $P(t)=U_\mathrm{q}I(t)$

\begin{tabular}[t]{p{9em}p{18em}}
$0 \leq t < t_1$: & $I(t)=I_0-2I_0t/t_1$

$t_1 \leq t < t_2$: & $I(t)=-I_0$

\end{tabular}

- \begin{tabular}[t]{p{9em}p{18em}}
$0 \leq t < t_1$: & $W(t)=U_\mathrm{q}I_0t(1-t/t_1)$

$t_1 \leq t < t_2$: & $W(t)=-U_\mathrm{q}I_0(t-t_1)$
\end{tabular}

\begin{tabular}{p{9em}p{18em}}
$0 \min \leq t < 60\min$: & $W(t)=24(t/ \dmin)\left(1-\dfrac{t/\dmin}{60}\right)\mathrm{W} \min$

$60 \min \leq t < 90\min$: & $W(t)=-24[(t/\dmin)-60]\mathrm{W}\min$
\end{tabular}

